snippets.supportsFormatCombination:
PointPillarScatterPlugin::supportsFormatCombination(
    int32_t pos,
    PluginTensorDesc const* inOut,
    int32_t nbInputs,
    int32_t nbOutputs) noexcept
{
    assert(nbInputs == 3 && nbOutputs == 1);
    if (pos == 0)
    {
        return isFp(inOut[pos].type) && inOut[pos].format == TensorFormat::kLINEAR;
    }
    if (pos == 1)
    {
        return inOut[pos].type == DataType::kINT32 && inOut[pos].format == TensorFormat::kLINEAR;
    }
    if (pos == 2)
    {
        return (inOut[pos].type == DataType::kFLOAT || inOut[pos].type == DataType::kHALF
                   || inOut[pos].type == DataType::kINT32 || inOut[pos].type == DataType::kBOOL)
            && inOut[pos].format == TensorFormat::kLINEAR;
    }
    return inOut[pos].type == inOut[0].type && inOut[pos].format == TensorFormat::kLINEAR;
}

snippets.getOutputDataType:
PointPillarScatterPlugin::getOutputDataType(int32_t, DataType const* inputTypes, int32_t) const noexcept
{
    return inputTypes[0];
}

snippets.getOutputDimensions:
PointPillarScatterPlugin::getOutputDimensions(
    int32_t,
    DimsExprs const* inputs,
    int32_t nbInputs,
    IExprBuilder& exprBuilder) noexcept
{
    assert(nbInputs == 3);
    DimsExprs out{};
    out.nbDims = 4;
    out.d[0] = exprBuilder.constant(mParams.numAgents);
    out.d[1] = inputs[0].d[1];
    out.d[2] = exprBuilder.constant(mParams.height);
    out.d[3] = exprBuilder.constant(mParams.width);
    return out;
}
